tool_input.command:
$dir = "D:\repository\skills\dsh\langgraph-orchestrator\.sessions"
Write-Output "=== 各模型出现频次（真实调用，来自 .costs.jsonl）==="
$files = Get-ChildItem $dir -Filter "*.costs.jsonl" -ErrorAction SilentlyContinue
$agg = @{}
foreach($f in $files){
  Get-Content $f.FullName | ForEach-Object {
    $o = $_ | ConvertFrom-Json -ErrorAction SilentlyContinue
    if($o -and $o.model){ $agg[$o.model] = ($agg[$o.model] + 1) }
  }
}
$agg.GetEnumerator() | Sort-Object Value -Descending | ForEach-Object { "{0,-32} calls={1}" -f $_.Key, $_.Value }
Write-Output "=== workbuddy-ai/hy3 是否真被调用过 ==="
$hit = $agg.ContainsKey('workbuddy-ai/hy3')
Write-Output "workbuddy-ai/hy3 in records: $hit"

# 查 magpie 网关是否暴露 free hy3 模型；以及 planner 实际走哪个
try {
  $r = Invoke-WebRequest "http://127.0.0.1:3425/v1/models" -UseBasicParsing -TimeoutSec 8
  $j = $r.Content | ConvertFrom-Json
  Write-Output "=== gateway models 含 hy3/preview? ==="
  $j.data | Where-Object { $_.id -match 'hy3|preview|free' } | Select-Object -ExpandProperty id
  Write-Output "=== 全部 model id 数量 ==="
  $j.data.Count
} catch { Write-Output "gateway /models err: $($_.Exception.Message)" }

foreach($d in "D:\repository\skills\dsh\langgraph-orchestrator","D:\repository\skills\dsh\token-models","D:\repository\skills\dsh","D:\repository\skills"){
  $git = Join-Path $d ".git"
  if(Test-Path $git){ $t = if((Get-Item $git -Force).PSIsContainer){"dir"}else{"file(gitlink/submodule)"}; "HAS .git ($t): $d" }
  else { "no .git: $d" }
}
Write-Output "=== 仓库根 ==="
cd "D:\repository\skills"
git rev-parse --show-toplevel 2>&1
Write-Output "=== 当前目录是否子模块 ==="
git config --file .gitmodules --get-regexp path 2>&1 | Select-String 'dsh'
